import React from 'react';
import { Box, Typography, useTheme } from '@mui/material';

type NewsItem = {
  id: number;
  title: string;
};

type Props = {
};

const NewsTicker: React.FC<Props> = () => {
  const theme = useTheme();

  return (
    <Box p={2}>
      {/* Title with colored bar */}
      <Box
        display="flex"
        alignItems="center"
        mb={2}
        sx={{ width: '100%' }}
      >
        <Box
          sx={{
            width: 6,
            height: 24,
            backgroundColor: theme.palette.primary.main,
            borderRadius: 1,
            mr: 1.5,
          }}
        />
        <Typography variant="h6" fontWeight={600}>
          ข่าวสารล่าสุด
        </Typography>
      </Box>

      {/* News Slider */}
      <Box
        sx={{
          overflowX: 'auto',
          whiteSpace: 'nowrap',
          display: 'flex',
          gap: 2,
          paddingY: 1,
          scrollSnapType: 'x mandatory',
          scrollbarWidth: 'none',
          '&::-webkit-scrollbar': { display: 'none' },
          backgroundColor: theme.palette.background.default,
          borderRadius: 2,
        }}
      >
        {newsList.map((item) => (
          <Box
            key={item.id}
            sx={{
              minWidth: '250px',
              scrollSnapAlign: 'start',
              backgroundColor: theme.palette.primary.main,
              color: '#fff',
              padding: 2,
              borderRadius: 2,
              boxShadow: 1,
              flexShrink: 0,
            }}
          >
            <Typography variant="body2" fontWeight={500}>
              {item.title}
            </Typography>
          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default NewsTicker;


const newsList = [
  { id: 1, title: 'เปิดตัว MacBook Air M4 รุ่นใหม่ล่าสุด' },
  { id: 2, title: 'โปรโมชั่นผ่อน 0% นานสูงสุด 24 เดือน' },
  { id: 3, title: 'สินค้าลดราคาพิเศษเฉพาะเดือนนี้' },
];
